te['_note']='తెలుగు పాఠ్యానికి స్థానిక వ్యవసాయ నిపుణుడు / స్థానిక తెలుగు వక్త సమీక్ష అవసరం. సాంకేతిక పదాల్లో కొన్ని English పదాలను ఉంచాం.'
# Retain older aliases used by earlier branch for backward compatibility.
te.update({k:v for k,v in translations.items() if k not in te})
(base/'te.json').write_text(json.dumps(te,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(f'Wrote {len(te)} Telugu locale keys; translated {sum(1 for k in en if te[k] != en[k])} including existing and new translations.')
